UPDATE INT_SERVERFUNCTION SET NAME = COALESCE(NULL, NAME), DESCRIPTION = COALESCE(NULL, DESCRIPTION), TYPE = COALESCE(NULL, TYPE), JDBC_ID = NULL, CODE = COALESCE('SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CR_ID'',crc.CR_ID,''CR_CODIGO'',cr.CODIGO,''CR_NOME'',cr.NOME,''CONTA_ID'',cc.ID,''CODIGO'',cc.CODIGO,''CONTA_NOME'',cc.NOME,''TIPO'',cc.TIPO,''DRIVER_TIPO'',d.NOME,''DRIVER_ID'',d.ID))
 FROM CR_CONTA crc
 JOIN CONTA_CONTABIL cc ON cc.ID = crc.CONTA_ID
 LEFT JOIN CENTRO_RESULTADO cr ON cr.ID = crc.CR_ID
 LEFT JOIN CONTA_DRIVER_EXCECAO cde ON cde.CR_ID = crc.CR_ID AND cde.CONTA_ID = crc.CONTA_ID AND cde.ATIVO = true
 LEFT JOIN CONTA_DRIVER cd ON cd.CONTA_ID = crc.CONTA_ID
 LEFT JOIN DRIVERS d ON d.ID = COALESCE(cde.PACOTE_ID, cd.PACOTE_ID, cde.DRIVER_ID, cd.DRIVER_ID)
 WHERE crc.CR_ID = {{crId}} AND crc.ATIVO = true AND d.ID IS NOT NULL AND d.ATIVO = ''true''),JSON_ARRAY()) AS CONFIGS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''CR_ID'',t.CR_ID,''CONTA_ID'',t.CONTA_ID,''MES'',t.MES,''VALOR'',t.VALOR,''QUANTIDADE'',t.QUANTIDADE,''VALOR_UNITARIO'',t.VALOR_UNITARIO)) FROM ORCAMENTO t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID = {{crId}}),JSON_ARRAY()) AS BUDGET,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''EMPRESA_ID'',t.EMPRESA_ID,''CR_ID'',t.CR_ID,''CONTA_ID'',t.CONTA_ID,''ANO'',t.ANO,''MES'',t.MES,''VALOR'',t.VALOR)) FROM REALIZADO_CONTABIL t WHERE t.CR_ID = {{crId}} AND t.ANO = {{anoPrev}}),JSON_ARRAY()) AS REALIZADO,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''EMPRESA_ID'',t.EMPRESA_ID,''CR_ID'',t.CR_ID,''CONTA_ID'',t.CONTA_ID,''ANO'',t.ANO,''MES'',t.MES,''VALOR'',t.VALOR)) FROM REALIZADO_CONTABIL t WHERE t.CR_ID = {{crId}} AND t.ANO = {{ano}}),JSON_ARRAY()) AS REALIZADO_ATUAL,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''CR_ID'',t.CR_ID,''CONTA_ID'',t.CONTA_ID,''MES'',t.MES,''VALOR'',t.VALOR,''QUANTIDADE'',t.QUANTIDADE,''VALOR_UNITARIO'',t.VALOR_UNITARIO)) FROM ORCAMENTO t WHERE t.CICLO_ID = {{controlCicloId}} AND t.CR_ID = {{crId}}),JSON_ARRAY()) AS ORC_CONTROLE,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''CR_ID'',t.CR_ID,''EMPRESA_ID'',t.EMPRESA_ID,''CARGO'',t.CARGO,''DATA_ADMISSAO'',t.DATA_ADMISSAO,''SALARIO'',t.SALARIO,''TIPO_CONTRATO'',t.TIPO_CONTRATO,''ATIVO'',t.ATIVO)) FROM COLABORADOR t WHERE t.CR_ID = {{crId}} AND t.ATIVO = ''true''),JSON_ARRAY()) AS COLABORADORES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''CR_ID'',t.CR_ID,''COLABORADOR_ID'',t.COLABORADOR_ID,''MES'',t.MES,''SALARIO'',t.SALARIO,''BENEFICIOS'',t.BENEFICIOS,''ENCARGOS'',t.ENCARGOS,''TOTAL'',t.TOTAL)) FROM ORCAMENTO_PESSOAL t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID = {{crId}}),JSON_ARRAY()) AS ORCAMENTO_PESSOAL,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''CR_ID'',t.CR_ID,''CARGO_ID'',t.CARGO_ID,''MES'',t.MES,''QUANTIDADE'',t.QUANTIDADE)) FROM PROJECAO_HEADCOUNT t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID = {{crId}}),JSON_ARRAY()) AS HEADCOUNT,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',cp.ID,''CICLO_ID'',cp.CICLO_ID,''CR_ID'',cp.CR_ID,''CARGO_ID'',cp.CARGO_ID,''MES_ENTRADA'',cp.MES_ENTRADA,''MOTIVO'',cp.MOTIVO,''CRIADO_EM'',cp.CRIADO_EM,''QTD_VAGAS'',cp.QTD_VAGAS,''CARGO_NOME'',cg.NOME,''SALARIO_MEDIO'',cg.SALARIO_MEDIO)) FROM CONTRATACAO_PROJETADA cp JOIN CARGO cg ON cg.ID = cp.CARGO_ID WHERE cp.CICLO_ID = {{cicloId}} AND cp.CR_ID = {{crId}}),JSON_ARRAY()) AS CONTRATACOES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',pd.ID,''CICLO_ID'',pd.CICLO_ID,''EMPRESA_ID'',pd.EMPRESA_ID,''PERCENTUAL'',pd.PERCENTUAL,''MES_APLICACAO'',pd.MES_APLICACAO,''CRIADO_EM'',pd.CRIADO_EM,''EMPRESA_NOME'',e.NOME)) FROM PREMISSA_DISSIDIO pd JOIN EMPRESA e ON e.ID = pd.EMPRESA_ID WHERE pd.CICLO_ID = {{cicloId}}),JSON_ARRAY()) AS DISSIDIOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',pt.ID,''CICLO_ID'',pt.CICLO_ID,''EMPRESA_ID'',pt.EMPRESA_ID,''PERCENTUAL'',pt.PERCENTUAL,''CRIADO_EM'',pt.CRIADO_EM,''EMPRESA_NOME'',e.NOME)) FROM PREMISSA_TURNOVER pt JOIN EMPRESA e ON e.ID = pt.EMPRESA_ID WHERE pt.CICLO_ID = {{cicloId}}),JSON_ARRAY()) AS TURNOVERS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',a.ID,''CICLO_ID'',a.CICLO_ID,''COLABORADOR_ID'',a.COLABORADOR_ID,''PERCENTUAL'',a.PERCENTUAL,''MES_APLICACAO'',a.MES_APLICACAO,''MOTIVO'',a.MOTIVO,''CRIADO_EM'',a.CRIADO_EM,''COLAB_NOME'',c.NOME,''SALARIO'',c.SALARIO)) FROM AUMENTO_SALARIAL a JOIN COLABORADOR c ON c.ID = a.COLABORADOR_ID WHERE a.CICLO_ID = {{cicloId}}),JSON_ARRAY()) AS AUMENTOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''CR_ID'',t.CR_ID,''CONTA_ID'',t.CONTA_ID,''TIPO_RECEITA'',t.TIPO_RECEITA,''ITEM_NOME'',t.ITEM_NOME,''LINHA'',t.LINHA,''MES'',t.MES,''VALOR'',t.VALOR,''CRIADO_EM'',t.CRIADO_EM)) FROM RECEITA_PREMISSA t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID = {{crId}}),JSON_ARRAY()) AS RECEITA_PREMISSA,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''CR_ID'',t.CR_ID,''CONTA_ID'',t.CONTA_ID,''PERCENTUAL'',t.PERCENTUAL,''MODO'',t.MODO,''JUSTIFICATIVA'',t.JUSTIFICATIVA,''CRIADO_EM'',t.CRIADO_EM)) FROM HIST_PREMISSA t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID = {{crId}}),JSON_ARRAY()) AS HIST_PREMISSA,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''FORMULA_ID'',t.FORMULA_ID,''CICLO_ID'',t.CICLO_ID,''CR_ID'',t.CR_ID,''MES'',t.MES,''VALOR'',t.VALOR)) FROM DRIVER_FORMULA_VALOR t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID = {{crId}}),JSON_ARRAY()) AS CLV,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''FORMULA_ID'',t.FORMULA_ID,''CR_ID'',t.CR_ID,''TIPO'',t.TIPO,''FORMULA'',t.FORMULA,''CRIADO_EM'',t.CRIADO_EM)) FROM DRIVER_FORMULA_CR t WHERE t.CR_ID = {{crId}}),JSON_ARRAY()) AS OVERRIDES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''CONTA_ID'',t.CONTA_ID,''PERCENTUAL'',t.PERCENTUAL,''CRIADO_EM'',t.CRIADO_EM)) FROM PREMISSA_IMPOSTO t WHERE t.CICLO_ID = {{cicloId}}),JSON_ARRAY()) AS IMPOSTO_CENTRAL,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''GESTOR_ID'',t.GESTOR_ID,''CR_ID'',t.CR_ID,''STATUS'',t.STATUS,''COMENTARIO'',t.COMENTARIO,''ATUALIZADO_EM'',t.ATUALIZADO_EM,''DRIVERS_CONFIRMADOS'',t.DRIVERS_CONFIRMADOS)) FROM ORCAMENTO_STATUS t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID = {{crId}} AND ({{gestorId}} = 0 OR t.GESTOR_ID = {{gestorId}})),JSON_ARRAY()) AS STATUS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''DRIVER_ID'',t.DRIVER_ID,''GESTOR_ID'',t.GESTOR_ID,''STATUS'',t.STATUS,''COMENTARIO'',t.COMENTARIO,''ATUALIZADO_EM'',t.ATUALIZADO_EM,''DRIVERS_CONFIRMADOS'',t.DRIVERS_CONFIRMADOS)) FROM PACOTE_STATUS t WHERE t.CICLO_ID = {{cicloId}}),JSON_ARRAY()) AS PACOTE_STATUS_ALL,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CICLO_ID'',t.CICLO_ID,''DRIVER_ID'',t.DRIVER_ID,''CR_ID'',t.CR_ID,''CONTA_ID'',t.CONTA_ID,''MES'',t.MES,''VALOR'',t.VALOR)) FROM ORCAMENTO_PACOTE t WHERE t.CICLO_ID = {{cicloId}} AND t.CR_ID = {{crId}}),JSON_ARRAY()) AS PKG_BUDGET', CODE), PUBLIC_EXECUTION = COALESCE(NULL, PUBLIC_EXECUTION), CRON_EXPRESSION = NULL, CRON_INPUT_JSON = NULL WHERE NAME = 'hotOrcDetalheCr';
